import { invoke } from "@tauri-apps/api/core";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";
import {
  incrementWireCounter,
  parseSshForwardError,
  parseWireCounter,
  wireCounterToBigInt,
  type DesktopClientContext,
  type KeyInventory,
  type KnownScopesInput,
  type OpenClientResult,
  type ScopeActivation,
  type SshForwardError,
  type SshForwardEventHint,
  type SshForwardHost,
  type SshForwardHostEvent,
  type SshForwardProfile,
  type SshForwardSnapshot,
  type WireCounter,
} from "@dam-hopper/ui/lib/ssh-forward-host";

export const NATIVE_SSH_FORWARD_COMMANDS = {
  openClient: "ssh_forward_open_client",
  activateScope: "ssh_forward_activate_scope",
  snapshot: "ssh_forward_snapshot",
  createProfile: "ssh_forward_create_profile",
  updateProfile: "ssh_forward_update_profile",
  deleteProfile: "ssh_forward_delete_profile",
  start: "ssh_forward_start",
  stop: "ssh_forward_stop",
  restart: "ssh_forward_restart",
  listKeys: "ssh_forward_list_keys",
  approveHost: "ssh_forward_approve_host",
  purgeScope: "ssh_forward_purge_scope",
} as const satisfies Record<Exclude<keyof SshForwardHost, "subscribe" | "dispose">, string>;

const IPC_UNAVAILABLE: SshForwardError = {
  code: "IPC_UNAVAILABLE",
  message: "Native SSH forwarding is temporarily unavailable.",
  retryable: true,
};

function validContext(value: unknown): value is DesktopClientContext {
  if (!value || typeof value !== "object") return false;
  const context = value as Record<string, unknown>;
  return typeof context.desktopInstanceId === "string" && typeof context.managerSessionId === "string" && Boolean(parseWireCounter(context.clientEpoch));
}
function sameContext(left: DesktopClientContext, right: DesktopClientContext): boolean {
  return left.desktopInstanceId === right.desktopInstanceId && left.managerSessionId === right.managerSessionId && left.clientEpoch === right.clientEpoch;
}
function isCounter(value: unknown): value is WireCounter { return Boolean(parseWireCounter(value)); }

export class NativeSshForwardHost implements SshForwardHost {
  private context: DesktopClientContext | null = null;
  private activationToken: WireCounter | null = null;
  private scopeId: string | null = null;
  private scopeGeneration: WireCounter | null = null;
  private snapshotState: SshForwardSnapshot | null = null;
  private knownScopes: KnownScopesInput = { status: "unavailable" };
  private operation = 0;
  private reopening = false;
  private snapshotInFlight = false;
  private snapshotTrailing = false;
  private readonly listeners = new Set<(event: SshForwardHostEvent) => void>();
  private unlisten: UnlistenFn | null = null;
  private listening: Promise<void> | null = null;
  private disposed = false;

  async openClient(knownScopes: KnownScopesInput): Promise<OpenClientResult> {
    this.knownScopes = knownScopes;
    await this.installListener();
    const result = await this.invoke<OpenClientResult>(NATIVE_SSH_FORWARD_COMMANDS.openClient, { input: { knownScopes } });
    if (!validContext(result?.context) || !isCounter(result.activationTokenFloor) || !isCounter(result.scopeGeneration) || (result.activeScopeId !== null && typeof result.activeScopeId !== "string")) throw IPC_UNAVAILABLE;
    this.context = result.context;
    this.activationToken = result.activationTokenFloor;
    this.scopeId = result.activeScopeId;
    this.scopeGeneration = result.scopeGeneration;
    this.snapshotState = null;
    return result;
  }

  async activateScope(scopeId: string | null): Promise<ScopeActivation> {
    if (!this.context || !this.activationToken) throw IPC_UNAVAILABLE;
    const token = incrementWireCounter(this.activationToken);
    if (!token) throw { ...IPC_UNAVAILABLE, code: "COUNTER_EXHAUSTED" as const };
    const operation = ++this.operation;
    const context = this.context;
    this.activationToken = token;
    this.scopeId = scopeId;
    this.snapshotState = null;
    const result = await this.invoke<ScopeActivation>(NATIVE_SSH_FORWARD_COMMANDS.activateScope, { input: { context, activationToken: token, scopeId } });
    if (!this.validActivation(result, context, token, scopeId)) throw IPC_UNAVAILABLE;
    if (operation === this.operation) {
      this.scopeGeneration = result.scopeGeneration;
      this.snapshotState = result.snapshot;
    }
    return result;
  }

  snapshot(): Promise<SshForwardSnapshot> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.snapshot, {}); }
  createProfile(profile: SshForwardProfile): Promise<SshForwardSnapshot> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.createProfile, { profile, expectedProfilesRevision: this.requireSnapshot().profilesRevision }); }
  updateProfile(profileId: string, expectedGeneration: WireCounter, profile: SshForwardProfile): Promise<SshForwardSnapshot> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.updateProfile, { profileId, expectedGeneration, profile, expectedProfilesRevision: this.requireSnapshot().profilesRevision }); }
  deleteProfile(profileId: string, expectedGeneration: WireCounter): Promise<SshForwardSnapshot> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.deleteProfile, { profileId, expectedGeneration, expectedProfilesRevision: this.requireSnapshot().profilesRevision }); }
  start(profileId: string, expectedGeneration: WireCounter): Promise<SshForwardSnapshot> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.start, { profileId, expectedGeneration }); }
  stop(profileId: string, expectedGeneration: WireCounter): Promise<SshForwardSnapshot> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.stop, { profileId, expectedGeneration }); }
  restart(profileId: string, expectedGeneration: WireCounter): Promise<SshForwardSnapshot> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.restart, { profileId, expectedGeneration }); }
  listKeys(): Promise<KeyInventory> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.listKeys, {}); }
  approveHost(profileId: string, expectedGeneration: WireCounter, challengeId: string, algorithm: string, fingerprint: string): Promise<SshForwardSnapshot> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.approveHost, { profileId, expectedGeneration, challengeId, algorithm, fingerprint, expectedTrustRevision: this.requireSnapshot().trustRevision }); }
  async purgeScope(scopeId: string, knownScopes: KnownScopesInput): Promise<{ scopeId: string; purged: boolean }> {
    if (!this.context || !this.activationToken) throw IPC_UNAVAILABLE;
    return this.invoke(NATIVE_SSH_FORWARD_COMMANDS.purgeScope, { input: { context: this.context, activationToken: this.activationToken, scopeId, knownScopes } });
  }
  subscribe(listener: (event: SshForwardHostEvent) => void): () => void { this.listeners.add(listener); return () => this.listeners.delete(listener); }
  dispose(): void { if (!this.disposed) { this.disposed = true; ++this.operation; this.unlisten?.(); this.unlisten = null; } }

  private async command<T>(command: string, extra: Record<string, unknown>): Promise<T> {
    if (!this.context || !this.activationToken || !this.scopeId || !this.scopeGeneration) throw IPC_UNAVAILABLE;
    const context = this.context;
    const token = this.activationToken;
    const scopeId = this.scopeId;
    const scopeGeneration = this.scopeGeneration;
    try {
      const result = await this.invoke<T>(command, { input: { context, activationToken: token, scopeId, scopeGeneration, ...extra } });
      if (!this.validBoundResult(result, context, token, scopeId, scopeGeneration)) throw IPC_UNAVAILABLE;
      if (this.isSnapshot(result)) this.snapshotState = result;
      return result;
    } catch (error) {
      if (parseSshForwardError(error)?.code !== "MANAGER_SESSION_MISMATCH" || this.reopening) throw error;
      this.reopening = true;
      try {
        await this.openClient(this.knownScopes);
        if (!this.scopeId) throw IPC_UNAVAILABLE;
        await this.activateScope(this.scopeId);
        return await this.command(command, extra);
      } finally { this.reopening = false; }
    }
  }
  private validActivation(value: unknown, context: DesktopClientContext, token: WireCounter, scopeId: string | null): value is ScopeActivation {
    if (!value || typeof value !== "object") return false;
    const result = value as ScopeActivation;
    return validContext(result.context) && sameContext(result.context, context) && result.activationToken === token && result.scopeId === scopeId && isCounter(result.scopeGeneration) && (result.snapshot === null || (scopeId !== null && this.validBoundResult(result.snapshot, context, token, scopeId, result.scopeGeneration)));
  }
  private validBoundResult(value: unknown, context: DesktopClientContext, token: WireCounter, scopeId: string, scopeGeneration: WireCounter): boolean {
    if (!value || typeof value !== "object") return false;
    const result = value as Partial<SshForwardSnapshot & KeyInventory>;
    return validContext(result.context) && sameContext(result.context, context) && result.scopeId === scopeId && result.scopeGeneration === scopeGeneration && ("activationToken" in result ? result.activationToken === token : true);
  }
  private requireSnapshot(): SshForwardSnapshot { if (!this.snapshotState) throw IPC_UNAVAILABLE; return this.snapshotState; }
  private isSnapshot(value: unknown): value is SshForwardSnapshot { return Boolean(value && typeof value === "object" && "profilesRevision" in value && "trustRevision" in value); }
  private async invoke<T>(command: string, input: Record<string, unknown>): Promise<T> { try { return await invoke<T>(command, input); } catch (error) { throw parseSshForwardError(error) ?? IPC_UNAVAILABLE; } }
  private async installListener(): Promise<void> {
    if (!this.listening) this.listening = listen<SshForwardEventHint>("ssh-forward:changed", (event) => this.handleHint(event.payload)).then((unlisten) => { if (this.disposed) unlisten(); else this.unlisten = unlisten; });
    return this.listening;
  }
  private handleHint(hint: SshForwardEventHint): void {
    const context = this.context;
    const snapshot = this.snapshotState;
    if (!context || !snapshot || hint.desktopInstanceId !== context.desktopInstanceId || hint.managerSessionId !== context.managerSessionId || hint.clientEpoch !== context.clientEpoch || hint.activationToken !== this.activationToken || hint.scopeId !== this.scopeId) return;
    if (![hint.scopeGeneration, hint.profilesRevision, hint.trustRevision].every(isCounter)) return;
    const stale = wireCounterToBigInt(hint.scopeGeneration) < wireCounterToBigInt(snapshot.scopeGeneration) || wireCounterToBigInt(hint.profilesRevision) < wireCounterToBigInt(snapshot.profilesRevision) || wireCounterToBigInt(hint.trustRevision) < wireCounterToBigInt(snapshot.trustRevision);
    if (stale) return;
    for (const listener of this.listeners) listener({ type: "changed", hint });
    this.requestHintSnapshot();
  }
  private requestHintSnapshot(): void {
    if (this.snapshotInFlight) { this.snapshotTrailing = true; return; }
    this.snapshotInFlight = true;
    void this.snapshot().catch(() => {}).finally(() => { this.snapshotInFlight = false; if (this.snapshotTrailing) { this.snapshotTrailing = false; this.requestHintSnapshot(); } });
  }
}

/** SSH forwarding native capability has currently shipped only on Windows. */
export function createNativeSshForwardHost(platform: string, enabled = true): NativeSshForwardHost | null { return enabled && platform === "windows" ? new NativeSshForwardHost() : null; }

